# Strict tool contract + bounded ReAct orchestrator loop (Python)
REFUND_SCHEMA = {
    "name": "issue_refund",
    "strict": True,
    "parameters": {
        "type": "object",
        "properties": {
            "order_id": {"type": "string", "pattern": "^ORD-[0-9]+$"},
            "amount_cents": {"type": "integer", "minimum": 1, "maximum": 50000},
            "idempotency_key": {"type": "string"}
        },
        "required": ["order_id", "amount_cents", "idempotency_key"],
        "additionalProperties": False
    }
}

def run_agent_loop(messages, tools, max_steps: int = 8):
    for step in range(max_steps):
        resp = llm_call(messages, tools=tools)
        if not resp.tool_calls:
            return resp.text
        for call in resp.tool_calls:
            obs = execute_sandboxed_tool(call.name, call.args)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": obs[:4000]})
    raise RuntimeError("Agent exceeded max_steps budget")
